protocol Foo {
    func doSomething()
}

extension Foo {
    func doSomething() {
        print(#line)
    }
}

class A: Foo {
    func doSomething() {
        print(#line)
    }
}

class B: Foo {}

let a = A()
a.doSomething()

let foo: Foo = A()
foo.doSomething()

let b = B()
b.doSomething()

func output<T>(_ param: T) where T: Comparable { print("Template") }
func output(_ param: Int) { print("Int") }
func output(_ param: Any) { print("Any") }

output(5)
output(true)
output(5 as Int64)

func foo<T: Equatable>(_ value: T) {
    print("Equatable")
}

func foo<T: Hashable>(_ value: T) {
    print("Hashable")
}

foo(5)

let main = DispatchQueue(label: "main")
let background = DispatchQueue(label: "background")

main.async {
    print("1")
    self.background.sync {
        sleep(1)
        print("2")
        self.main.sync {
            print("3")
        }
    }
    print("4")
}

func application(_ application: UIApplication, didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
    DispatchQueue.main.sync {
        print("Hello world")
    }
    return true
}
